<?php
namespace Modules\PriyasaCore\Http\Controllers\Storefront;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Modules\PriyasaCore\Models\CommerceConversation; use Modules\PriyasaCore\Models\CommerceConversationMessage; use Modules\PriyasaCore\Jobs\SendWhatsAppInteractive;
class WhatsAppCommerceController extends Controller { public function sendInteractive(Request $r){$data=$r->validate(['phone'=>'required|string|max:40','type'=>'required|in:buttons,list,image,template,product','body'=>'nullable|string|max:4096','buttons'=>'array','sections'=>'array','button_text'=>'nullable|string|max:20','url'=>'nullable|url|max:2048','caption'=>'nullable|string|max:1024','name'=>'nullable|string|max:128','language'=>'nullable|string|max:16','components'=>'array','catalog_id'=>'nullable|string|max:191','product_retailer_id'=>'nullable|string|max:191','header'=>'nullable|string|max:60','footer'=>'nullable|string|max:60']);$conv=CommerceConversation::firstOrCreate(['channel'=>'whatsapp','external_id'=>$data['phone']],['status'=>'open']);$msg=CommerceConversationMessage::create(['conversation_id'=>$conv->id,'direction'=>'outbound','message'=>$data['body']??null,'message_type'=>$data['type'],'metadata'=>$data]);SendWhatsAppInteractive::dispatch($msg->id,$data['phone'],$data);return response()->json(['queued'=>true,'message_id'=>$msg->id],202);}}
